import React, { useState, useEffect, useRef, useMemo } from "react";
import { useParams, useNavigate } from "react-router-dom";
import Button from "../components/common/Button";
import OptionButton from "../components/common/OptionButton";
import ConflictCard from "../components/common/ConflictCard";
import Stepper from "../components/common/Stepper";
import { useUI } from "../context/UIContext";
import {
  questionsDCIS,
  questionsBctSm,
  getBctSmResult,
  topicDescriptions,
} from "../constants/sdm";
import styles from "../Questionnaire.module.css";
import { saveToSheet } from "../components/utils/googleSheetLogger";
import {
  checkBctSmConflict,
  getBctSmFinalResult,
} from "../components/utils/decisionLogic";

// ─── Phase 狀態機 ──────────────────────────────────────────────
// SPEAKING   : eve_sdm_talk.mp4 循環播放 + Web Speech TTS 念旁白
// VIDEO      : TTS 念完 → 補充 YouTube 影片疊在小幫手上（全版）
// VIDEO_MINI : YouTube 影片播完 → 縮到右下角，小幫手重現
// READY      : 全部解鎖：右上角頭像亮起、選項浮出、按鈕可點
const PHASE = {
  SPEAKING:   "speaking",
  VIDEO:      "video",
  VIDEO_MINI: "video_mini",
  READY:      "ready",
};

const Questionnaire = () => {
  const { topicKey } = useParams();
  const navigate = useNavigate();
  const { setHeroData, allAnswers, setAllAnswers } = useUI();

  const questionSet = useMemo(
    () => (topicKey === "dcis" ? questionsDCIS : questionsBctSm),
    [topicKey]
  );

  // ─── 原有 state ─────────────────────────────────────────────
  const [currentId, setCurrentId] = useState(questionSet[0].id);
  const [history, setHistory] = useState([]);
  const [answers, setAnswers] = useState({});
  const [isVideoFinished, setIsVideoFinished] = useState(false);
  const [viewedPages, setViewedPages] = useState(new Set());
  const [viewedCases, setViewedCases] = useState(new Set());
  const [completedRoutes, setCompletedRoutes] = useState(new Set());
  const [isConflictMode, setIsConflictMode] = useState(false);
  const [conflictData, setConflictData] = useState(null);
  const [conflictChoice, setConflictChoice] = useState(null);

  // ─── 小幫手 phase state ──────────────────────────────────────
  const [phase, setPhase] = useState(PHASE.SPEAKING);
  const fallbackTimerRef = useRef(null);
  // eve_sdm_talk.mp4 的 <video> ref，用來控制播放 / 暫停
  const talkVideoRef = useRef(null);
  // YouTube iframe ref，用於重新掛載（換節點時重置影片）
  const iframeKeyRef = useRef(0);
  const [iframeKey, setIframeKey] = useState(0);

  const currentQ = questionSet.find((q) => q.id === currentId);

  // ─── 解析 YouTube videoId ────────────────────────────────────
  const videoId = currentQ?.videoUrl?.match(
    /(?:v=|\/embed\/|youtu\.be\/)([^"&?\/\s]{11})/
  )?.[1] ?? null;

  // ─── 節點切換 → 重置 phase + 啟動 TTS ──────────────────────
  useEffect(() => {
    if (isConflictMode) return;

    // 取消上一節點殘留的 TTS 與 timer
    window.speechSynthesis.cancel();
    clearTimeout(fallbackTimerRef.current);

    // 換節點時讓 iframe 重新掛載（清除上一節點的 YouTube 狀態）
    iframeKeyRef.current += 1;
    setIframeKey(iframeKeyRef.current);

    // eve_sdm_talk.mp4：重頭播
    if (talkVideoRef.current) {
      talkVideoRef.current.currentTime = 0;
      talkVideoRef.current.play().catch(() => {});
    }

    // 沒有旁白腳本 → 直接跳過 SPEAKING
    if (!currentQ?.assistantScript) {
      if (talkVideoRef.current) talkVideoRef.current.pause();
      // 若此節點有影片，跳到 VIDEO；否則直接 READY
      setPhase(videoId ? PHASE.VIDEO : PHASE.READY);
      return;
    }

    setPhase(PHASE.SPEAKING);

    const utter = new SpeechSynthesisUtterance(currentQ.assistantScript);
    utter.lang  = "zh-TW";
    utter.rate  = 0.9;

    const advanceFromSpeaking = () => {
      clearTimeout(fallbackTimerRef.current);
      // TTS 念完 → 停止說話動畫
      if (talkVideoRef.current) talkVideoRef.current.pause();
      // 念完後：有補充影片 → VIDEO，否則 → READY
      setPhase(videoId ? PHASE.VIDEO : PHASE.READY);
    };

    // 保底 timeout（iOS / 部分 Android Chrome onend 不一定觸發）
    const fallbackMs = currentQ.assistantScript.length * 160 + 1500;
    fallbackTimerRef.current = setTimeout(advanceFromSpeaking, fallbackMs);
    utter.onend = advanceFromSpeaking;

    window.speechSynthesis.speak(utter);

    return () => {
      window.speechSynthesis.cancel();
      clearTimeout(fallbackTimerRef.current);
      if (talkVideoRef.current) talkVideoRef.current.pause();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentId, isConflictMode]);

  // ─── topicKey 切換清空答案 ──────────────────────────────────
  useEffect(() => {
    setAllAnswers((prev) => ({ ...prev, answers: {} }));
    setAnswers({});
    setHistory([]);
  }, [topicKey, setAllAnswers]);

  // ─── Hero 資料 ───────────────────────────────────────────────
  useEffect(() => {
    window.scrollTo(0, 0);
    setHeroData({
      imageUrl: "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: topicDescriptions[topicKey]?.label || "問卷評估",
      description: isConflictMode
        ? "請針對您的顧慮做出最後權衡。"
        : "請詳閱說明再做出選擇或點擊下一步。",
    });
  }, [currentId, isConflictMode, topicKey, setHeroData]);

  // ─── 路由追蹤 ────────────────────────────────────────────────
  useEffect(() => {
    const caseIds = ["SM_CASE_1_RAD", "SM_CASE_2", "SM_CASE_3", "SM_CASE_4"];
    if (caseIds.includes(currentId))
      setViewedCases((prev) => new Set(prev).add(currentId));
    if (currentId === "BCT_A7_FINISH")
      setCompletedRoutes((prev) => new Set(prev).add("BCT"));
    if (currentId === "SM_B6_FINISH")
      setCompletedRoutes((prev) => new Set(prev).add("SM"));
  }, [currentId]);

  // ─── YouTube 播放結束偵測（postMessage）────────────────────
  useEffect(() => {
    // 若此節點已看過或已作答，直接視為完成
    setIsVideoFinished(
      viewedPages.has(currentId) || answers[currentId] !== undefined
    );

    const handleYTMessage = (event) => {
      if (event.origin !== "https://www.youtube.com") return;
      try {
        const data =
          typeof event.data === "string" ? JSON.parse(event.data) : event.data;
        // playerState === 0 代表影片播完（ended）
        if (data.info?.playerState === 0 || data.playerState === 0) {
          setIsVideoFinished(true);
          setViewedPages((prev) => new Set(prev).add(currentId));
          // 影片播完 → 進入 VIDEO_MINI，小幫手靜態圖重現，選項準備浮出
          setPhase(PHASE.VIDEO_MINI);
        }
      } catch (_e) {
        // JSON.parse 失敗時忽略
      }
    };

    window.addEventListener("message", handleYTMessage);
    return () => window.removeEventListener("message", handleYTMessage);
  }, [currentId, viewedPages, answers]);

  // ─── VIDEO_MINI → READY（短暫延遲，讓縮圖動畫完成後解鎖）──
  useEffect(() => {
    if (phase !== PHASE.VIDEO_MINI) return;
    const timer = setTimeout(() => setPhase(PHASE.READY), 600);
    return () => clearTimeout(timer);
  }, [phase]);

  // ─── 衍生狀態 ────────────────────────────────────────────────
  const isAllCasesViewed   = viewedCases.size >= 4;
  const isBothRoutesViewed = completedRoutes.has("BCT") && completedRoutes.has("SM");

  // phase 便利 flag
  const isSpeaking  = phase === PHASE.SPEAKING;
  const isVideoFull = phase === PHASE.VIDEO;
  const isVideoMini = phase === PHASE.VIDEO_MINI;
  const isReady     = phase === PHASE.READY;

  // VIDEO / VIDEO_MINI / READY 三個 phase 都要顯示 iframe（避免重新載入）
  const showVideoIframe = videoId && !isSpeaking;

  // ─── 導航邏輯（原有不動）────────────────────────────────────
  const handleBack = () => {
    if (isConflictMode) return setIsConflictMode(false);
    if (history.length > 0) {
      const lastId = history[history.length - 1];
      setHistory(history.slice(0, -1));
      setCurrentId(lastId);
    } else {
      navigate(`/SDM?step=INTRO&topic=${topicKey}`);
    }
  };

  const finishAssessment = (finalAnswers, ultimateChoice = null) => {
    let result;
    if (topicKey === "bctsm") {
      result = ultimateChoice
        ? getBctSmFinalResult(ultimateChoice, finalAnswers)
        : getBctSmResult(finalAnswers);
    } else {
      const selected = currentQ?.options?.find(
        (opt) => opt.label === finalAnswers[currentId]
      );
      result = {
        title:       selected?.resultTitle       || "評估完成",
        description: selected?.resultDescription || "請與醫師討論",
        type:        selected?.type              || "",
      };
    }

    const dataToSave = Object.keys(finalAnswers)
      .filter((id) => {
        const qDef = questionSet.find((q) => q.id === id);
        const excludedIds = [
          "BCTSM_START", "BCT_A7_FINISH", "SM_B6_FINISH", "SM_B3_TREATMENT_MATRIX",
        ];
        return qDef && qDef.options?.length >= 2 && !excludedIds.includes(id);
      })
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
      .map((id) => finalAnswers[id]);

    const finalRowData = [...dataToSave];
    if (topicKey === "bctsm") finalRowData.push(ultimateChoice || "無衝突");

    saveToSheet({
      userName:      allAnswers.userName,
      birthDate:     allAnswers.birthDate || allAnswers.birthday,
      selectedTopic: topicDescriptions[topicKey]?.label,
      answers_map:   finalRowData,
      finalResult:   result.title,
    });

    navigate("/result", { state: { finalData: result } });
  };

  const handleNext = () => {
    if (currentQ.videoUrl && !isVideoFinished) return alert("請完整觀看影片");
    const currentChoice = answers[currentId];
    if (currentQ.options?.length > 0 && !currentChoice) return alert("請先點選選項");

    const latestAnswers = {
      ...allAnswers.answers,
      ...answers,
      [currentId]: currentChoice || "下一步",
    };
    setAllAnswers((prev) => ({ ...prev, answers: latestAnswers }));

    const selectedOpt = currentQ.options?.find((opt) => opt.label === currentChoice);

    if (currentQ.isFinal || selectedOpt?.isFinal) {
      if (topicKey === "bctsm") {
        const conflict = checkBctSmConflict(latestAnswers);
        if (conflict.hasConflict) {
          setConflictData(conflict);
          setIsConflictMode(true);
          return;
        }
      }
      finishAssessment(latestAnswers);
    } else {
      const nextId = selectedOpt?.nextId || currentQ.nextId;
      setHistory([...history, currentId]);
      setCurrentId(nextId);
    }
  };

  const getRouteInfo = () => {
    if (isConflictMode)
      return { label: "解決選擇衝突", color: "#ff4d4f" };
    if (currentId.startsWith("BCT_"))
      return { label: "體驗中：部分乳房切除合併前哨淋巴結切片流程", color: "#1890ff" };
    if (currentId.startsWith("SM_"))
      return { label: "體驗中：全乳房切除合併前哨淋巴結切片流程", color: "#52c41a" };
    if (currentId.startsWith("Q_"))
      return { label: "正在釐清您的偏好", color: "#fa8c16" };
    if (currentId === "BCTSM_START")
      return { label: "請選擇想要體驗的流程", color: "#722ed1" };
    if (currentId === "DCIS_Q1")
      return { label: "請選擇手術方式", color: "#722ed1" };
    if (currentId.includes("DCIS_") && currentId.includes("_BCT"))
      return { label: "目前選擇：部分乳房切除", color: "#1890ff" };
    if (currentId.includes("DCIS_") && currentId.includes("_SLN"))
      return { label: "目前選擇：部分切除合併前哨淋巴結切片", color: "#13c2c2" };
    return null;
  };

  const routeInfo = getRouteInfo();

  if (!currentQ && !isConflictMode)
    return <div className={styles.container}>正在生成結果...</div>;

  // ─── Render ──────────────────────────────────────────────────
  return (
    <div className={styles.container}>

      {/* ── Sticky Header ── */}
      <div className={styles.stickyHeader}>
        <Stepper topicKey={topicKey} currentId={currentId} isConflictMode={isConflictMode} />
        {routeInfo && (
          <div className={styles.routeHeader}>
            <span className={styles.routeBadge} style={{ backgroundColor: routeInfo.color }}>
              {routeInfo.label}
            </span>
          </div>
        )}
      </div>

      {isConflictMode ? (
        /* ── 衝突模式 ── */
        <ConflictCard
          conflictData={conflictData}
          conflictChoice={conflictChoice}
          setConflictChoice={setConflictChoice}
          onBack={() => setIsConflictMode(false)}
          onFinish={(txt) => finishAssessment(allAnswers.answers, txt)}
          isEmbedded={true}
        />
      ) : (
        <>
          {/* ══════════════════════════════════════════════════════
              小幫手舞台區
              ─ 結構 ─────────────────────────────────────────────
              assistantWrapper（相對定位）
                ├─ ① eve_sdm_talk.mp4  SPEAKING 時播放
                ├─ ② helperinside.png  非 SPEAKING 時顯示
                ├─ ③ YouTube iframe    VIDEO → 全版覆蓋；VIDEO_MINI/READY → fixed 右下縮圖
                ├─ ④ 右上角頭像        READY 才亮起（問問題入口）
                └─ ⑤ 字幕條            SPEAKING 時在 wrapper 底部顯示旁白
          ══════════════════════════════════════════════════════ */}
          <div className={styles.assistantWrapper}>

            {/* ① 說話動畫：SPEAKING 才顯示，其他 phase 淡出 */}
            <video
              ref={talkVideoRef}
              src="/assets/eve_sdm_talk.mp4"
              loop
              muted
              playsInline
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                objectFit: "contain",
                opacity: isSpeaking ? 1 : 0,
                transition: "opacity 0.4s",
                pointerEvents: "none",
              }}
            />

            {/* ② 靜止圖：TTS 結束後出現（VIDEO 全版時會被 iframe 蓋住，正常） */}
            <img
              src="/assets/helperinside.png"
              alt="小幫手"
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                objectFit: "contain",
                opacity: isSpeaking ? 0 : 1,
                transition: "opacity 0.4s",
                pointerEvents: "none",
              }}
            />

            {/* ③ YouTube 補充影片
                VIDEO（全版）  : absolute inset:0，蓋住整個 wrapper，autoplay=1
                VIDEO_MINI / READY（縮圖）: fixed 右下角，點擊切回全版 */}
            {showVideoIframe && (
              isVideoFull ? (
                /* ── 全版 ── */
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    zIndex: 10,
                    borderRadius: 8,
                    overflow: "hidden",
                  }}
                >
                  <iframe
                    key={iframeKey}
                    src={`https://www.youtube.com/embed/${videoId}?enablejsapi=1&origin=${window.location.origin}&rel=0&autoplay=1`}
                    title="補充影片"
                    frameBorder="0"
                    allow="autoplay; fullscreen"
                    allowFullScreen
                    style={{
                      width: "100%",
                      aspectRatio: "16/9",
                      display: "block",
                    }}
                  />
                </div>
              ) : (
                /* ── 縮圖（VIDEO_MINI 或 READY）── */
                <div
                  onClick={() => setPhase(PHASE.VIDEO)}
                  title="點擊重看影片"
                  style={{
                    position: "fixed",
                    bottom: 16,
                    right: 16,
                    width: 220,
                    borderRadius: 8,
                    overflow: "hidden",
                    boxShadow: "0 4px 16px rgba(0,0,0,0.35)",
                    zIndex: 50,
                    cursor: "pointer",
                    transition: "transform 0.4s ease, opacity 0.4s ease",
                    transform: isVideoMini ? "scale(0.85)" : "scale(1)",
                    opacity: isVideoMini ? 0.7 : 1,
                  }}
                >
                  {/* iframe 在縮圖狀態下保持存在（不重新載入），但關閉 pointer-events */}
                  <iframe
                    key={iframeKey}
                    src={`https://www.youtube.com/embed/${videoId}?enablejsapi=1&origin=${window.location.origin}&rel=0`}
                    title="補充影片（縮圖）"
                    frameBorder="0"
                    allow="autoplay; fullscreen"
                    allowFullScreen
                    style={{
                      width: "100%",
                      aspectRatio: "16/9",
                      display: "block",
                      pointerEvents: "none", // 讓外層 div 的 onClick 能觸發
                    }}
                  />
                  {/* 重看遮罩 */}
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      background: "rgba(0,0,0,0.38)",
                      color: "#fff",
                      fontSize: 12,
                      fontWeight: 600,
                      letterSpacing: "0.04em",
                    }}
                  >
                    ▶ 重看影片
                  </div>
                </div>
              )
            )}

            {/* ④ 右上角問問題頭像：只有 READY 才解鎖 */}
            <div
              className={styles.helperAvatar}
              title={isReady ? "問小幫手問題" : "請先聽完說明才能發問"}
              style={{
                opacity: isReady ? 1 : 0.3,
                cursor: isReady ? "pointer" : "not-allowed",
                transition: "opacity 0.4s",
              }}
              onClick={() => isReady && navigate("/chatbot")}
            >
              <img src="/assets/helperinside.png" alt="問問題" />
              {isReady && <span className={styles.helperAvatarDot} />}
            </div>

            {/* ⑤ 字幕條：SPEAKING 時在 wrapper 底部顯示當前旁白 */}
            {isSpeaking && currentQ?.assistantScript && (
              <div className={styles.assistantCaption}>
                {currentQ.assistantScript}
              </div>
            )}

          </div>

          {/* ══════════════════════════════════════════════════════
              問題 + 選項 + 按鈕：READY 才完全解鎖浮出
              （VIDEO_MINI 期間也保持隱藏，讓縮圖動畫完成後再顯示）
          ══════════════════════════════════════════════════════ */}
          <div
            style={{
              opacity: isReady ? 1 : 0,
              transform: isReady ? "translateY(0)" : "translateY(24px)",
              transition: "opacity 0.5s ease, transform 0.5s ease",
              pointerEvents: isReady ? "auto" : "none",
            }}
          >
            <h3
              className={styles.questionTitle}
              dangerouslySetInnerHTML={{ __html: currentQ.question || currentQ.topic }}
            />

            <div className={styles.optionsGroup}>
              {currentQ.options?.map((opt, index) => {
                const isSMMatrix = currentId === "SM_B3_TREATMENT_MATRIX";
                const isFinished =
                  (isSMMatrix &&
                    viewedCases.has(
                      opt.nextId === "SM_CASE_1" ? "SM_CASE_1_RAD" : opt.nextId
                    )) ||
                  (opt.nextId === "BCT_A1_OP" && completedRoutes.has("BCT")) ||
                  (opt.nextId === "SM_B1_OP"  && completedRoutes.has("SM"));

                const isDisabled =
                  (currentQ.videoUrl && !isVideoFinished) ||
                  (isSMMatrix && opt.nextId === "SM_B6_FINISH" && !isAllCasesViewed) ||
                  (opt.nextId === "Q_APPEARANCE" && !isBothRoutesViewed);

                return (
                  <OptionButton
                    key={`${currentId}-${index}`}
                    label={`${isFinished ? "✓ " : ""}${opt.label}`}
                    isSelected={answers[currentId] === opt.label}
                    isDisabled={isDisabled}
                    onClick={() => setAnswers({ ...answers, [currentId]: opt.label })}
                    style={isFinished ? { borderColor: "#52c41a", color: "#52c41a" } : {}}
                  />
                );
              })}
            </div>

            <div className={styles.actionGroup}>
              <Button variant="outline" onClick={handleBack} style={{ flex: 1 }}>
                {history.length === 0 ? "返回介紹" : "上一步"}
              </Button>
              <Button onClick={handleNext} style={{ flex: 1 }}>
                {currentQ.isFinal ? "查看結果" : "下一步"}
              </Button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default Questionnaire;
